def transform(grid):
 h=len(grid); w=len(grid[0]); out=[r[:] for r in grid]
 seen=set(); sources=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c]==0 or (r,c) in seen: continue
   col=grid[r][c]; comp=[(r,c)]; seen.add((r,c))
   for x,y in comp:
    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
     a,b=x+dx,y+dy
     if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==col:
      seen.add((a,b)); comp.append((a,b))
   if len(comp)==1: sources.append((r,c,col))
 for r,c,col in sources:
  reached={(r,c)}; q=[(r,c)]
  for x,y in q:
   for dx in range(-2,3):
    for dy in range(-2,3):
     if abs(dx)+abs(dy)>2: continue
     a,b=x+dx,y+dy
     if 0<=a<h and 0<=b<w and grid[a][b]!=0 and (a,b) not in reached:
      reached.add((a,b)); q.append((a,b))
  for a,b in reached: out[a][b]=col
 for r,c,col in sources: out[r][c]=0
 return out

